<div class="general-settings-actions"><?php if($reminderdecisionState['can_write']&&!$draft['pending']):?><button class="btn btn-solid theme-primary" name="reminder_decision_intent" value="preview"><?=e($rdt('Ganze Versandentscheidung unverbindlich prüfen'))?></button><?php endif;if(!$draft['pending']):?><button class="btn btn-outline theme-secondary" name="reminder_decision_intent" value="discard"><?=e($rdt('Eigenen ungespeicherten Entscheidungsentwurf verwerfen'))?></button><?php endif;if($reminderdecisionState['can_write']&&($draft['pending']||$draft['conflicted'])):?><button class="btn btn-outline theme-secondary" name="reminder_decision_intent" value="current"><?=e($rdt('Ganze Entscheidungsangaben mit aktuellem Stand erneut prüfen'))?></button><?php endif ?></div>
<?php if($review&&!$draft['pending']):?><section class="card" data-reminder-decision-review><h4><?=e($rdt('Geprüfte, noch nicht ausgeführte Versandentscheidung'))?></h4><p><?=e($rdt($rdOperations[$review['input']['operation']]))?></p><p><?=e($review['source']['recipient'])?></p><p><?=e($rdt($reminderStatuses[$review['source']['state']]))?></p>
<?=hidden('reminder_decision_key',$draft['key'])?><?php if($reminderdecisionState['can_write']):?><label class="general-settings-check"><input class="check" type="checkbox" name="reminder_decision_approved" value="1"><span><?=e($rdt('Genau dieser ursprüngliche Auftrag, sein bisheriger Stand, die Aktion sowie meine ganzen Angaben und Nachweise sind geprüft.'))?></span></label><button class="btn btn-solid theme-primary" name="reminder_decision_intent" value="accept"><?=e($rdt('Geprüfte Versandentscheidung bewusst speichern'))?></button><?php endif ?></section><?php endif ?></form></section><?php endif ?>
<?php $history=$reminderdecisionState['history'];$historyQuery=is_string($_GET['reminder_decision_history_q']??'')?($_GET['reminder_decision_history_q']??''):'';$historyPage=is_string($_GET['reminder_decision_history_page']??'1')?($_GET['reminder_decision_history_page']??'1'):'';?><section class="card" data-reminder-decision-history><h4><?=e($rdt('Eigene frühere Versandentscheidungen'))?></h4>
<form method="get" class="general-settings-page-form" novalidate><?=hidden('view','documents').hidden('doc',$reminderDocument).hidden('reminder_invoice',$reminderInvoice).hidden('reminder_job',$reminderdecisionJob)?><label><?=e($rdt('Ganze Entscheidungssuche'))?><?php $rf('reminder_decision_history_q',$historyQuery);?></label><label><?=e($rdt('Genaue Entscheidungsseite'))?><?php $rf('reminder_decision_history_page',$historyPage);?></label><button class="btn btn-outline theme-secondary"><?=e($rdt('Genau diese eigenen Versandentscheidungen anzeigen'))?></button></form>
<?php if($history&&$history['error']===''):?><p><?=e(str_replace(['{page}','{pages}','{count}'],[(string)$history['page'],(string)$history['pages'],(string)$history['total']],$rdt('Seite {page} von {pages} · {count} eigene Bestätigungen')))?></p><ul><?php foreach($history['rows']as$row):?><li><a href="<?=e($rdu(['reminder_decision_receipt'=>$row['request_key'],'reminder_decision_history_q'=>$history['query'],'reminder_decision_history_page'=>$history['page_input']]))?>#invoice-reminder-decision"><?=e(localDateTime($row['created_at']))?></a></li><?php endforeach ?></ul><?php endif ?></section></section>
